    type: arrow.kind === 'dotted' ? 'dotted' : arrow.kind === 'thick' ? 'thick' : undefined,
    label: label || undefined, bidir: undefined,
    waypoints: undefined, attributes: undefined, comments: undefined,
    pos: toPos(line),
