    ctx.groupStack.pop();
    return;
  }
  if (/^subgraph\b/.test(line)) {
    parseSubgraph(ctx, line, lineNo);
    return;
  }
  if (parseEdgeLine(ctx, line, lineNo)) return;
  // bare node-definition line(s)
  const probe = readEndpoints({ ...ctx } as FlowCtx, line, 0, lineNo);
  void probe;
  const saved = { objects: ctx.objects.length, links: ctx.links.length, diags: ctx.diags.length };
  const ok = parseBareNodes(ctx, line, lineNo);
  if (!ok) {
    ctx.objects.length = saved.objects;
    ctx.diags.length = saved.diags;
    ctx.diags.push(diag(M.unsupported, `unrecognized line skipped: ${line}`, lineNo, 1, 'warning'));
