};

const parseBareNodes = (ctx: FlowCtx, line: string, lineNo: number): boolean => {
  let j = 0;
  let count = 0;
  for (;;) {
    while (line[j] === ' ' || line[j] === '\t') j += 1;
    if (j >= line.length) return count > 0;
    const node = readNode(line, j);
    if (!node) return false;
    const obj = ensureNode(ctx, node, lineNo);
    ctx.nodes.set(obj.id, obj);
    count += 1;
    j = node.end;
    const sep = /^\s*&\s*/.exec(line.slice(j));
    if (!sep) return j >= line.length ? true : false;
    j += sep[0].length;
  }
};

const DIRS: Record<string, Doc['direction']> = { TD: 'TB', TB: 'TB', LR: 'LR', RL: 'RL', BT: 'BT' };

/** Convert mermaid `flowchart`/`graph` text to a PDL Doc. */
export function fromMermaid(src: string): MermaidResult {
  const ctx: FlowCtx = { ...newCtx(), nodes: new Map() };
  let direction: Doc['direction'] = undefined;
  let inFrontmatter = false;
  const lines = src.split('\n');
  for (let n = 0; n < lines.length; n += 1) {
    const line = lines[n]!.trim();
    const lineNo = n + 1;
    if (inFrontmatter) {
      if (line === '---') inFrontmatter = false;
      else ctx.diags.push(diag(M.unsupported, `frontmatter line skipped: ${line}`, lineNo, 1, 'warning'));
      continue;
    }
    if (line === '---' && n === 0) {
      inFrontmatter = true;
      continue;
    }
    if (line === '' || line.startsWith('%%')) continue;
    const head = /^(flowchart|graph)(?:\s+([A-Za-z]{1,2}))?\s*$/.exec(line);
    if (head) {
      const dir = head[2] === undefined ? undefined : DIRS[head[2]];
      if (dir === undefined && head[2] !== undefined) {
        ctx.diags.push(diag(M.unsupported, `unsupported direction "${head[2]}"`, lineNo, 1, 'warning'));
      }
      direction = dir ?? direction;
      continue;
    }
    flowLine(ctx, lines[n]!, lineNo);
  }
  const doc: Doc = {
    irVersion: IR_VERSION,
    formatVersion: '1.0',
    title: undefined, level: 'container', direction, theme: undefined, comments: undefined,
    imports: [], objects: ctx.objects, links: ctx.links, flows: [], views: [], styles: [],
  };
  return { doc, diagnostics: ctx.diags };
}
