const SHAPE_RES: { re: RegExp; kind: Obj['kind'] }[] = [
  { re: /^\(\[\s*([^\]]*?)\s*\]\)/, kind: 'system_ext' },
  { re: /^\(\(\s*([^)]*?)\s*\)\)/, kind: 'person' },
  { re: /^\[\(\s*([^)]*?)\s*\)\]/, kind: 'datastore' },
  { re: /^\(\s*([^)]*?)\s*\)/, kind: 'component' },
  { re: /^\[\s*([^\]]*?)\s*\]/, kind: 'container' },
  { re: /^\{\s*([^}]*?)\s*\}/, kind: 'note' },
