    { re: /^--(.+?)-->/, kind: 'plain' },
    { re: /^-\.+->/, kind: 'dotted' },
    { re: /^-\.+?(.*?)\.+->/, kind: 'dotted' },
    { re: /^={2,}>/, kind: 'thick' },
    { re: /^==(.+?)==+>/, kind: 'thick' },
    { re: /^-{3,}(?![>.])/, kind: 'undir' },
