const parseBareNodes = (ctx: ConvertCtx, line: string, lineNo: number): boolean => {
  let j = 0;
  let count = 0;
  for (;;) {
    while (line[j] === ' ' || line[j] === '\t') j += 1;
    const node = readNode(line, j);
    if (!node) return false;
    ensureNode(ctx, node, lineNo);
    count += 1;
    j = node.end;
    const sep = /^\s*&/.exec(line.slice(j));
    if (!sep) break;
    j += sep[0].length;
