    if (head) {
      const dir = head[2] === undefined ? undefined : DIRS[head[2]];
      if (head[2] !== undefined && dir === undefined) {
        ctx.diags.push(diag(M.unsupported, `unsupported direction "${head[2]}"`, lineNo, 1, 'warning'));
      }
      direction = dir ?? direction;
      continue;
