	objects map[string]bool
	aliases map[string]bool
	groups  map[string]bool
	flows   map[string]bool
	views   map[string]bool
	links   map[string]bool
}

func toSet(xs []string) map[string]bool {
	s := map[string]bool{}
	for _, x := range xs {
		s[x] = true
	}
	return s
}

func collectIds(doc *ir.Doc) ids {
	flowIDs := map[string]bool{}
	for i := range doc.Flows {
		if doc.Flows[i].ID != "" {
			flowIDs[doc.Flows[i].ID] = true
		}
	}
	viewIDs := map[string]bool{}
	for i := range doc.Views {
		if doc.Views[i].ID != "" {
			viewIDs[doc.Views[i].ID] = true
		}
	}
	linkIDs := map[string]bool{}
	for i := range doc.Links {
		if doc.Links[i].ID != "" {
			linkIDs[doc.Links[i].ID] = true
		}
	}
	groups := map[string]bool{}
	objIDs := map[string]bool{}
	for i := range doc.Objects {
		o := &doc.Objects[i]
		objIDs[o.ID] = true
		if o.Kind == "group" {
			groups[o.ID] = true
		}
	}
	aliases := map[string]bool{}
	for i := range doc.Imports {
		aliases[doc.Imports[i].Alias] = true
	}
	return ids{objects: objIDs, aliases: aliases, groups: groups, flows: flowIDs, views: viewIDs, links: linkIDs}
}

func endpointOk(id string, s ids) bool { return s.objects[id] || s.aliases[id] }

// --- P100 --------------------------------------------------------------------

func checkDupIds(doc *ir.Doc) []Diagnostic {
