			seen[id] = true
		}
	}
	objs := map[string]bool{}
	for i := range doc.Objects {
		o := &doc.Objects[i]
		if objs[o.ID] {
			out = append(out, diag("P100", fmt.Sprintf("duplicate object id \"%s\"", o.ID), o.Pos.Line, o.Pos.Col))
		}
		objs[o.ID] = true
	}
	var flowIDs []string
	flowPos := map[string]ir.Pos{}
	for i := range doc.Flows {
		f := &doc.Flows[i]
		flowIDs = append(flowIDs, f.ID)
		flowPos[f.ID] = f.Pos
	}
	dup("flow", flowIDs, 0, 0)
	_ = flowPos
	var viewIDs []string
	for i := range doc.Views {
		viewIDs = append(viewIDs, doc.Views[i].ID)
	}
	dup("view", viewIDs, 0, 0)
	return out
}
