    21  // runConvert executes the convert command; returns the process exit code.
    22  func runConvert(args []string, stdout, stderr io.Writer) int {
    23  	flags := flag.NewFlagSet("convert", flag.ExitOnError)
    24  	outDir := flags.String("out", "", "write output files here (default: next to each input)")
    25  	if err := flags.Parse(args); err != nil {
    26  		fmt.Fprintf(stderr, "panelcraft: %v\n", err)
    27  		return 2
    28  	}
