    30  	if err != nil {
    31  		fmt.Fprintf(stderr, "panelcraft: %v\n", err)
    32  		return 2
    33  	}
    34  	if *outDir != "" {
    35  		if err := os.MkdirAll(*outDir, 0o755); err != nil {
    36  			fmt.Fprintf(stderr, "panelcraft: %v\n", err)
    37  			return 2
    38  		}
    39  	}
    40  
    41  	exit := 0
    42  	for _, path := range files {
    43  		code := convertOne(path, *outDir, stdout, stderr)
    44  		if code > exit {
    45  			exit = code
    46  		}
    47  	}
    48  	return exit
    49  }
    50  
    51  func convertOne(path, outDir string, stdout, stderr io.Writer) int {
    52  	src, err := os.ReadFile(path)
    53  	if err != nil {
    54  		fmt.Fprintf(stderr, "panelcraft: %v\n", err)
    55  		return 2
    56  	}
    57  	res := pdl.Parse(string(src))
    58  	if res.Doc == nil {
    59  		printDiags(stderr, path, res.Diagnostics)
    60  		fmt.Fprintf(stderr, "panelcraft: %s: parse failed, no IR written\n", path)
    61  		return 1
    62  	}
    63  	out, err := ir.Marshal(res.Doc)
    64  	if err != nil {
    65  		fmt.Fprintf(stderr, "panelcraft: %s: %v\n", path, err)
    66  		return 1
    67  	}
    68  	target := irTargetPath(path, outDir)
    69  	if err := os.WriteFile(target, out, 0o644); err != nil {
    70  		fmt.Fprintf(stderr, "panelcraft: %v\n", err)
    71  		return 1
    72  	}
    73  	fmt.Fprintf(stdout, "wrote %s\n", target)
    74  	return 0
    75  }
    76  
    77  // irTargetPath: foo.pcd → foo.ir.json (or DIR/foo.ir.json with --out).
    78  func irTargetPath(path, outDir string) string {
    79  	base := strings.TrimSuffix(filepath.Base(path), filepath.Ext(path)) + ".ir.json"
    80  	if outDir != "" {
    81  		return filepath.Join(outDir, base)
    82  	}
    83  	return filepath.Join(filepath.Dir(path), base)
