   127  		return 2
   128  	}
   129  	files, err := expandPaths(flags.Args())
   130  	if err != nil {
   131  		fmt.Fprintf(stderr, "panelcraft: %v\n", err)
   132  		return 2
   133  	}
   134  	if len(files) == 0 {
   135  		fmt.Fprintf(stderr, "panelcraft: validate takes at least one PATH\n")
   136  		return 2
   137  	}
   138  	cwd, err := os.Getwd()
   139  	if err != nil {
   140  		fmt.Fprintf(stderr, "panelcraft: %v\n", err)
   141  		return 2
   142  	}
   143  	probe := fsImports{workspace: cwd}
