		ds := v(head+"import b as \"b.pcd\"\nimport c as \"c.pcd\"\nperson a \"A\"\n", mapImports{
			graph: map[string][]string{"b.pcd": {"d.pcd"}, "c.pcd": {"d.pcd"}, "d.pcd": {}},
